import './style.css';
function Clicker(){
 const [count,setCount] = useState(Number(localStorage.getItem('counter')) || 0);
 const incrementCount = ()=>{
 setCount((prev)=>prev+1);
 }

 useEffect(()=>{
 localStorage.setItem('counter',count);
 },[count]);
